<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import Shell from '../Layouts/Shell.vue';
import { computed, watch } from 'vue';
import WorkLog from '../Components/WorkLog.vue';
import AttachmentUpload from '../Components/AttachmentUpload.vue';
import AttachmentGallery from '../Components/AttachmentGallery.vue';
import TicketApproval from '../Components/TicketApproval.vue';
defineOptions({inheritAttrs:false});
const props = defineProps<{ticket:{source:string|null;reporter_name:string|null;rating:number|null;rated_by:string|null;category:string;priority:string;created_at:string;closed_at:string|null;assignee:{name:string}|null;id:number;version:number;description:string;status:string;equipment:{id:number;name:string}|null;club:{name:string};assignee_id:number|null;work_result:string|null;verification_result:string|null;cause:string|null;solution:string|null;events:{id:number;from_status:string;to_status:string;comment:string|null;created_at:string}[]};assignable:{id:number;name:string}[];transitions:string[];canEdit:boolean;canAttach:boolean;canDecide:boolean;proposals:{id:number;description:string;amount_minor:number;currency:string;expected_duration:string;status:string;author_name:string;decision_name:string|null;decision_comment:string|null;created_at:string;decided_at:string|null}[];attachments:{id:number;name:string;mime:string;stage:string|null}[];workLogs:{id:number;minutes:number;actions:string;cost_minor:number;currency:string;consumables:string|null}[]}>();
const page=usePage<{auth:{user:{role:string}}}>();
const labels:Record<string,string>={new:'Новая',accepted:'Принята',working:'В работе',approval:'Ожидает согласования',parts:'Ожидает запчастей',resolved:'Решена',closed:'Закрыта'};
const form=useForm({status:props.transitions[0],version:props.ticket.version,work_result:props.ticket.work_result??'',verification_result:props.ticket.verification_result??'',cause:props.ticket.cause??'',solution:props.ticket.solution??'',comment:''});
const cleaning=computed(()=>/чистк/iu.test(props.ticket.category));
const tasks=['Корпус и фильтры очищены','Вентиляторы очищены','Радиаторы очищены','Пыль удалена с комплектующих','Термопаста заменена'];
function toggleTask(task:string){const lines=form.work_result.split('\n').filter(Boolean);form.work_result=(lines.includes(task)?lines.filter(x=>x!==task):[...lines,task]).join('\n');}
const assignment=useForm({assignee_id:props.ticket.assignee_id??'',version:props.ticket.version});
watch(()=>props.ticket.version, value=>{form.version=value; assignment.version=value; form.status=props.transitions[0];});
function date(value:string|null){return value?new Date(value).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'}):'—';}
</script>
<template><Head :title="'Заявка #'+ticket.id" /><Shell>
  <div class="heading"><div><p class="eyebrow">{{ ticket.club.name }}</p><h1>Заявка #{{ ticket.id }}</h1><p v-if="ticket.source || ticket.rating" class="ticket-origin"><span v-if="ticket.source==='telegram'">Из Telegram-группы клуба{{ ticket.reporter_name ? ' · ' + ticket.reporter_name : '' }}</span><span v-else-if="ticket.source==='link'">Создана автоматически: сетевой линк не восстановился{{ ticket.reporter_name ? ' · ответил ' + ticket.reporter_name : '' }}</span><span v-if="ticket.rating" class="ticket-rating" :aria-label="'Оценка клиента ' + ticket.rating + ' из 5'">{{ '★'.repeat(ticket.rating) + '☆'.repeat(5 - ticket.rating) }}<small v-if="ticket.rated_by"> {{ ticket.rated_by }}</small></span></p></div><span class="badge">{{ labels[ticket.status] }}</span></div>
  <p v-if="ticket.status==='closed' && !canEdit && !canAttach" class="panel">Заявка закрыта. Доступен только просмотр результатов, фотографий и истории.</p><section class="panel ticket-summary"><div class="summary-heading"><h2>Сведения о заявке</h2><Link href="/tickets" class="secondary back-link">← Все заявки</Link></div><p class="ticket-description">{{ticket.description}}</p><div class="table-scroll"><table class="summary-table"><tbody><tr><th>Клуб</th><td>{{ticket.club.name}}</td><th>Оборудование</th><td><Link v-if="ticket.equipment" :href="'/equipment/'+ticket.equipment.id">{{ticket.equipment.name}}</Link><span v-else>Общая заявка</span></td></tr><tr><th>Исполнитель</th><td>{{ticket.assignee?.name || 'Не назначен'}}</td><th>Категория</th><td>{{ticket.category}}</td></tr><tr><th>Приоритет</th><td>{{({low:'Низкий',normal:'Обычный',high:'Высокий',critical:'Критический'} as Record<string,string>)[ticket.priority] || ticket.priority}}</td><th>Создана</th><td>{{date(ticket.created_at)}}</td></tr><tr v-if="ticket.closed_at"><th>Закрыта</th><td colspan="3">{{date(ticket.closed_at)}}</td></tr></tbody></table></div><nav class="ticket-nav" aria-label="Разделы заявки"><a href="#ticket-result">Результат и работы</a><a href="#ticket-photos">Фотографии · {{attachments.length}}</a><a href="#ticket-history">История · {{ticket.events.length}}</a></nav></section>
  <form v-if="canEdit && ['owner','lead'].includes(page.props.auth.user.role)" class="panel toolbar" @submit.prevent="assignment.post('/tickets/'+ticket.id+'/assign')"><label>Исполнитель<select v-model="assignment.assignee_id" required><option v-for="u in assignable" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><button :disabled="assignment.processing">Назначить</button><p class="error" v-for="error in assignment.errors" :key="error">{{ error }}</p></form>
  <form id="ticket-result" v-if="canEdit && transitions.length" class="panel form-grid" @submit.prevent="form.post('/tickets/'+ticket.id+'/transition')">
    <div v-if="cleaning" class="cleaning-checklist"><h2>Чистка ПК</h2><p>Отметьте только выполненные работы.</p><label v-for="task in tasks" :key="task"><input type="checkbox" :checked="form.work_result.split('\n').includes(task)" @change="toggleTask(task)"/>{{task}}</label></div><label>{{cleaning ? 'Что очищено / дополнительные работы' : 'Выполненные работы'}}<textarea v-model="form.work_result" /></label><label>Результат проверки<textarea v-model="form.verification_result" /></label><label v-if="!cleaning">Причина<textarea v-model="form.cause" /></label><label v-if="!cleaning">Решение<textarea v-model="form.solution" /></label><label>Комментарий<textarea v-model="form.comment" /></label><label>Следующий статус<select v-model="form.status"><option v-for="s in transitions" :key="s" :value="s">{{ labels[s] }}</option></select></label>
    <p class="error" role="alert" v-for="(error,key) in form.errors" :key="key">{{ error }}</p><button :disabled="form.processing">{{ form.processing?'Сохраняем…':'Сохранить переход' }}</button>
  </form>
  <section v-else id="ticket-result" class="panel"><h2>Результат</h2><table class="result-table"><tbody><tr v-for="(label,key) in {work_result:'Выполненные работы',verification_result:'Проверка',cause:'Причина',solution:'Решение'}" :key="key"><th>{{label}}</th><td class="prewrap">{{ticket[key] || 'Не указано'}}</td></tr></tbody></table></section>  <TicketApproval :ticket-id="ticket.id" :version="ticket.version" :status="ticket.status" :can-edit="canEdit" :can-decide="canDecide" :proposals="proposals"/><WorkLog v-if="canEdit" :ticket-id="ticket.id"/><section id="ticket-photos" v-if="cleaning" class="panel"><h2>Фотоотчёт о чистке</h2><p>Добавьте общий вид и крупные планы. Фотографии отображаются сразу после загрузки.</p><div class="cleaning-photos"><section v-for="stage in ([ 'before', 'after' ] as const)" :key="stage"><h3>{{stage === 'before' ? 'До чистки' : 'После чистки'}}</h3><AttachmentUpload v-if="canAttach" type="ticket" :id="ticket.id" :stage="stage"/><AttachmentGallery :attachments="attachments.filter(a=>a.stage===stage)"/></section></div></section><section :id="cleaning?undefined:'ticket-photos'" class="panel"><h2>{{cleaning ? 'Другие вложения' : 'Вложения'}}</h2><AttachmentUpload v-if="canAttach" type="ticket" :id="ticket.id"/><AttachmentGallery :attachments="cleaning ? attachments.filter(a=>!a.stage) : attachments"/></section><section v-if="workLogs.length" class="panel"><h2>Учёт работ и расходов</h2><div class="table-scroll"><table><thead><tr><th>Работы</th><th>Время</th><th>Расходы</th><th>Материалы</th></tr></thead><tbody><tr v-for="w in workLogs" :key="w.id"><td class="prewrap">{{w.actions}}</td><td>{{w.minutes}} мин</td><td>{{(w.cost_minor/100).toFixed(2)}} {{w.currency}}</td><td>{{w.consumables || '—'}}</td></tr></tbody></table></div></section><section id="ticket-history" class="panel"><h2>История</h2><p v-if="!ticket.events.length">Изменений пока нет.</p><article v-for="event in ticket.events" :key="event.id" class="event"><strong>{{ labels[event.from_status] }} → {{ labels[event.to_status] }}</strong><p>{{ event.comment }}</p><small>{{ new Date(event.created_at).toLocaleString('ru-RU', {timeZone:'Asia/Tashkent'}) }} · Asia/Tashkent</small></article></section>
</Shell></template>

<style scoped>
.ticket-summary .summary-table{min-width:0;table-layout:fixed}.summary-table th,.result-table th{white-space:normal}.summary-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.back-link{padding:10px 14px;border:1px solid var(--border);border-radius:8px}.ticket-description{font-size:18px;line-height:1.6;margin:20px 0;white-space:pre-wrap;overflow-wrap:anywhere}.summary-table,.result-table{width:100%;border-collapse:collapse}.summary-table th,.result-table th{text-align:left;color:var(--muted);font-weight:500;width:16%;font-size:12px}.summary-table td,.summary-table th,.result-table th,.result-table td{padding:14px 12px;border-bottom:1px solid var(--border);vertical-align:top;overflow-wrap:anywhere}.result-table{margin-top:16px;table-layout:fixed}.result-table th{width:25%}.ticket-nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.ticket-nav a{padding:12px 16px;border:1px solid var(--border);border-radius:8px;color:var(--text);background:var(--hover);font-weight:600}.ticket-nav a:hover{border-color:var(--accent-text)}#ticket-result,#ticket-photos,#ticket-history{scroll-margin-top:90px}@media(max-width:700px){.summary-table,.summary-table tbody{display:block}.summary-table tr{display:grid;grid-template-columns:1fr 1fr}.summary-table th,.summary-table td{width:auto;min-width:0}.result-table th{width:34%}.ticket-description{font-size:16px}.ticket-nav a{flex:1;text-align:center}}
.cleaning-checklist{grid-column:1/-1;padding:20px;background:var(--hover);border-radius:10px}.cleaning-checklist label{display:flex;flex-direction:row;align-items:center;gap:12px;margin:12px 0}.cleaning-checklist input{width:18px;height:18px}.cleaning-photos{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:20px}.cleaning-photos>section{min-width:0}h3{font-size:18px;font-weight:600}@media(max-width:900px){.cleaning-photos{grid-template-columns:1fr}}
.ticket-origin{margin:4px 0 0;display:flex;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:13px}
.ticket-rating{color:var(--warning,#d4a017);letter-spacing:1px}
.ticket-rating small{color:var(--muted);letter-spacing:0}
</style>
